import { promises as fs } from "fs";
import * as path from "path";
import type { StorageProvider } from "./types";

/**
 * Disk storage for development and tests. Keys are generated by the attachment
 * service (never from a user's file name) and are still re-checked here so a key can
 * never escape the base directory.
 */
export class LocalStorageProvider implements StorageProvider {
  readonly name = "local" as const;

  constructor(private readonly baseDir: string) {}

  private resolve(key: string) {
    if (!/^[A-Za-z0-9_\-./]+$/.test(key) || key.includes("..")) throw new Error("invalid storage key");
    const full = path.resolve(this.baseDir, key);
    if (!full.startsWith(path.resolve(this.baseDir) + path.sep)) throw new Error("invalid storage key");
    return full;
  }

  async put(key: string, bytes: Uint8Array, _contentType?: string) {
    const full = this.resolve(key);
    await fs.mkdir(path.dirname(full), { recursive: true });
    await fs.writeFile(full, bytes, { flag: "wx" }); // wx: never overwrite
  }

  async get(key: string) {
    return new Uint8Array(await fs.readFile(this.resolve(key)));
  }

  async remove(key: string) {
    await fs.rm(this.resolve(key), { force: true });
  }
}
